from copy import deepcopy


def rotate_clockwise(board):
    if isinstance(board, (str, bytes)):
        raise TypeError("board must be a sequence of rows")
    try:
        rows = list(board)
    except TypeError as exc:
        raise TypeError("board must be a sequence of rows") from exc
    n = len(rows)
    normalized = []
    for row in rows:
        if isinstance(row, (str, bytes)):
            raise TypeError("rows must be sequences")
        try:
            cells = list(row)
        except TypeError as exc:
            raise TypeError("rows must be sequences") from exc
        if len(cells) != n:
            raise ValueError("board must be square")
        normalized.append(cells)
    return [[deepcopy(normalized[column][row]) for column in range(n)] for row in range(n)]
